<?php namespace Database\Seeders; use Illuminate\Database\Seeder; use App\Models\{User,Project,Task,Payment}; use Illuminate\Support\Facades\Hash; class DatabaseSeeder extends Seeder{public function run(){ $a=User::updateOrCreate(['email'=>'admin@agency.test'],['name'=>'Agency Admin','password'=>Hash::make('password'),'role'=>'admin']);$c=User::updateOrCreate(['email'=>'client@agency.test'],['name'=>'Acme Client','password'=>Hash::make('password'),'role'=>'client']);$t=User::updateOrCreate(['email'=>'team@agency.test'],['name'=>'Team Member','password'=>Hash::make('password'),'role'=>'team']);$i=User::updateOrCreate(['email'=>'intern@agency.test'],['name'=>'Agency Intern','password'=>Hash::make('password'),'role'=>'intern']);$p=Project::updateOrCreate(['slug'=>'acme-growth-website'],['client_id'=>$c->id,'name'=>'Acme Growth Website','description'=>'Conversion-focused agency project.','status'=>'active','priority'=>'high','budget'=>4800,'due_date'=>now()->addDays(25),'progress'=>50]);$p->members()->sync([$t->id,$i->id]);Task::updateOrCreate(['project_id'=>$p->id,'title'=>'Build responsive hero'],['assignee_id'=>$t->id,'created_by'=>$a->id,'status'=>'in_progress','priority'=>'high','due_date'=>now()->addDays(3)]);Task::updateOrCreate(['project_id'=>$p->id,'title'=>'Run QA checklist'],['assignee_id'=>$i->id,'created_by'=>$a->id,'status'=>'todo','priority'=>'medium','due_date'=>now()->addDays(7)]);Payment::updateOrCreate(['project_id'=>$p->id,'reference'=>'ACME-001'],['amount'=>2400,'currency'=>'USD','status'=>'paid','method'=>'Bank Transfer','paid_at'=>now()]);}}
